package com.travel.meomulkyung.itinerary.domain;
import com.travel.meomulkyung.region.domain.Region; import com.travel.meomulkyung.user.domain.User; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import java.time.LocalDateTime;
@Entity @Table(name="completed_trips") @Getter @NoArgsConstructor public class CompletedTrip { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="completed_trip_id") private Long id; @OneToOne(optional=false) @JoinColumn(name="itinerary_id",unique=true) private Itinerary itinerary; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(optional=false) @JoinColumn(name="region_id") private Region region; private int stayHours; private int partySize; private long totalSpent; private LocalDateTime completedAt; public CompletedTrip(Itinerary i,int h,int p,long total){itinerary=i;user=i.getUser();region=i.getRegion();stayHours=h;partySize=p;totalSpent=total;completedAt=LocalDateTime.now();}}
